this.add({id:1556, 
title:"Sample Granular Policies", 
body:" sample granular policies this topic provides sample policies use reference. create policy scans files structured content like parquet avro. {\n\t\"name\": \"policy skip structured content\",\n\t\"cloud_provider\": \"aws\"\n\t\"dlp\": {\n\t\t\"profilenames\": [\"victoria - health records act 2001\", \"test custom dlp profile changed\"]\n\t},\n\t\"enabled\": true,\n\t\"objectconditional\": {\n\t\t\"blocklist\": {\n\t\t\t\"extension\": {\n\t\t\t\t\"in\": [\".parquet\", \".avro\"]\n\t\t\t}\n\t\t}\n\t},\n\t\"maxscanfrequency\": \"24h\",\n\t\"action\": \"alert\",\n\t\"notify\": {\n\t\t\"interval\": \"30\",\n\t\t\"to_users\": [\n\t\t\t\"admin\"\n\t\t],\n\t\t\"emails\": [\n\t\t\t\"abc@netskope.com\"\n\t\t],\n\t\t\"from_user\": \"abc@netskope.com\"\n\t}\n} create policy scans files bucket. {\n\t\"name\": \"policy skip bucket\",\n\t\"cloud_provider\": \"aws\"\n\t\"dlp\": {\n\t\t\"profilenames\": [\"victoria - health records act 2001\", \"test custom dlp profile changed\"]\n\t},\n\t\"enabled\": true,\n\t\"objectcontainerconditional\": {\n\t\t\"blocklist\": {\n\t\t\t\"name\": {\n\t\t\t\t\"in\": [\"bucket-not-to-be-scanned\"]\n\t\t\t}\n\t\t}\n\t},\n\t\"maxscanfrequency\": \"24h\",\n\t\"action\": \"alert\",\n\t\"notify\": {\n\t\t\"interval\": \"30\",\n\t\t\"to_users\": [\n\t\t\t\"admin\"\n\t\t],\n\t\t\"emails\": [\n\t\t\t\"abc@netskope.com\"\n\t\t],\n\t\t\"from_user\": \"abc@netskope.com\"\n\t}\n} create policy scans list buckets skips structured content files. {\n\t\"name\": \"policy scan list buckets sparing structured files\",\n\t\"cloud_provider\": \"aws\"\n\t\"dlp\": {\n\t\t\"profilenames\": [\"victoria - health records act 2001\", \"test custom dlp profile changed\"]\n\t},\n\t\"enabled\": true,\n\t\"objectcontainerconditional\": {\n\t\t\"allowlist\": {\n\t\t\t\"name\": {\n\t\t\t\t\"in\": [\"bucket-1-to-be-scanned\", \"bucket-2-to-be-scanned\"]\n\t\t\t}\n\t\t}\n\t},\n\t\"objectconditional\": {\n\t\t\"blocklist\": {\n\t\t\t\"extension\": [\".parquet\", \".avro\"]\n\t\t\t}\n\t\t}\n\t},\n\t\"maxscanfrequency\": \"24h\",\n\t\"action\": \"alert\",\n\t\"notify\": {\n\t\t\"interval\": \"30\",\n\t\t\"to_users\": [\n\t\t\t\"admin\"\n\t\t],\n\t\t\"emails\": [\n\t\t\t\"abc@netskope.com\"\n\t\t],\n\t\t\"from_user\": \"abc@netskope.com\"\n\t}\n} " });
